    justify-content: center;
  }
  .phone {
    width: 550px;
    min-height: 720px;
    background: #ffffff;
    position: relative;
    padding-bottom: 30px;
  }
  /* status bar */
  .status-bar {
    height: 38px;
    display: flex;
    align-items: center;
    justify-content: flex-end;
    padding: 0 15px;
    font-size: 13px;
    color: #000;
  }
  .status-bar .icons {
    margin-left: 8px;
  }
  .close-btn {
    padding: 10px 20px 20px 20px;
    font-size: 22px;
    color: #333;
  }
  .content {
    padding: 0 22px;
  }

  /* Section 5 heading */
  .section-heading {
    display: flex;
    align-items: center;
    margin-top: 10px;
    margin-bottom: 14px;
  }
  .num-badge {
    background: #f3a6a6;
    color: #fff;
    width: 22px;
    height: 22px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 14px;
    font-weight: bold;
    margin-right: 10px;
    flex-shrink: 0;
