    margin: 0 0 26px 0;
    text-align: justify;
  }

  /* Section 2 centered heading with big number */
  .big-heading {
    display: flex;
    justify-content: center;
    align-items: baseline;
    margin: 20px 0 30px 0;
    position: relative;
  }
  .big-heading .big-num {
    font-size: 46px;
    font-weight: bold;
    color: #7b6fd1;
    line-height: 1;
    position: relative;
  }
  .big-heading .dot {
    position: absolute;
    right: -4px;
    bottom: 8px;
    width: 6px;
    height: 6px;
    background: #7b6fd1;
    border-radius: 50%;
  }
  .big-heading .big-title {
    font-size: 20px;
